import {sheetThumbnail} from './thumbnails.js';
export function installLayers(E){let dragged=null,collapsed=new Set(),filter='';function enhance(){for(const row of document.querySelectorAll('.layer')){row.draggable=true;row.hidden=!!filter&&!row.textContent.toLowerCase().includes(filter);const b=E.doc.blocks.find(b=>b.id===row.dataset.id);if(b?.groupIds?.some(g=>collapsed.has(g)))row.hidden=true;if(b){row.style.setProperty('--layer-depth',b.groupIds?.length||0);if(!row.querySelector('.layer-thumb')){const thumb=document.createElement('span');thumb.className='layer-thumb';thumb.innerHTML=sheetThumbnail(E.doc,E.source.skills,E.imageCache,{blocks:[b],className:'layer-preview',label:'Prévia: '+(b.layerName||b.title)});row.prepend(thumb);}}}const section=document.querySelector('.layer')?.parentElement;if(section&&!section.querySelector('.layer-search')){const search=document.createElement('input');search.className='layer-search';search.placeholder='Buscar camada…';search.setAttribute('aria-label','Buscar camada');search.value=filter;search.oninput=()=>{filter=search.value.toLowerCase();enhance();};section.prepend(search);}for(const row of document.querySelectorAll('.layer-group-row')){if(!row.querySelector('.group-preview')){const preview=document.createElement('span');preview.className='layer-thumb group-preview';preview.innerHTML=sheetThumbnail(E.doc,E.source.skills,E.imageCache,{blocks:E.doc.blocks.filter(b=>b.groupIds?.includes(row.dataset.id)),className:'layer-preview',label:'Prévia do grupo'});row.prepend(preview);}if(row.querySelector('[data-collapse]'))continue;const button=document.createElement('span');button.dataset.collapse=row.dataset.id;button.textContent=collapsed.has(row.dataset.id)?'▸':'▾';button.title='Recolher ou expandir grupo';button.style.padding='0 6px';row.prepend(button);}}
 document.addEventListener('click',e=>{const lock=e.target.dataset.groupLock,hide=e.target.dataset.groupHide;if(lock||hide){e.preventDefault();e.stopImmediatePropagation();const blocks=E.doc.blocks.filter(b=>b.groupIds?.includes(lock||hide)),key=lock?'locked':'visible',value=lock?!blocks.every(b=>b.locked):!blocks.some(b=>b.visible);E.change(()=>blocks.forEach(b=>b[key]=value),true,true);return;}const id=e.target.dataset.collapse;if(id){e.preventDefault();e.stopImmediatePropagation();collapsed.has(id)?collapsed.delete(id):collapsed.add(id);enhance();}},true);
 document.addEventListener('dragstart',e=>{const row=e.target.closest('.layer');if(!row)return;dragged=row.dataset.id;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged);});document.addEventListener('dragover',e=>{const row=e.target.closest('.layer');if(row&&dragged){e.preventDefault();row.classList.add('drag-over');}});document.addEventListener('dragleave',e=>e.target.closest('.layer')?.classList.remove('drag-over'));document.addEventListener('drop',e=>{const row=e.target.closest('.layer');if(!row||!dragged)return;e.preventDefault();const from=E.doc.blocks.find(b=>b.id===dragged),target=E.doc.blocks.find(b=>b.id===row.dataset.id);if(from&&target&&from!==target&&!from.locked)E.change(()=>{const all=E.doc.blocks.filter(b=>from.groupIds?.length?b.groupIds?.includes(from.groupIds.at(-1)):b.id===from.id);E.doc.blocks=E.doc.blocks.filter(b=>!all.includes(b));const index=E.doc.blocks.indexOf(target);E.doc.blocks.splice(Math.max(0,index+1),0,...all);},true,true);dragged=null;});
 document.addEventListener('dblclick',e=>{const name=e.target.closest('.layer-name');if(!name)return;const row=name.closest('.layer'),b=E.doc.blocks.find(b=>b.id===row.dataset.id);if(!b||b.locked)return;e.stopImmediatePropagation();const input=document.createElement('input');input.value=b.layerName||b.title;name.replaceChildren(input);input.focus();input.select();let done=false;const finish=()=>{if(done)return;done=true;E.change(()=>b.layerName=input.value||b.title,true,true);};input.onblur=finish;input.onkeydown=ev=>{ev.stopPropagation();if(ev.key==='Enter')finish();if(ev.key==='Escape'){done=true;E.inspector();}};},true);return {enhance};}
